tool_input_args.value:
# Extract the cancellation section from the policies text
import re

# Find the cancellation section
cancel_match = re.search(r'## cancel.*?(?=\n## |\Z)', policies, re.DOTALL)
if cancel_match:
    cancel_section = cancel_match.group(0)
    print(cancel_section)
else:
    print("No cancellation section found. Searching for related keywords...")
    # Print lines containing 'cancel'
    for line in policies.split('\n'):
        if 'cancel' in line.lower():
            print(line)

